import React, { use } from "react";
import orderImg from "@/public/images/order-bag.svg";
import Image from "next/image";
import { Button, QueryBoundary } from "@/app/_components/common/Index";
import { userFetchClient } from "@/app/_fetch/fetchData";
import { Collapse } from "@/app/_components/common/Collapse";
import OrderCancel from "../_compoenets/OrderCancel";
import Pagination from "../_compoenets/Pagination";

const page = ({ searchParams }) => {
  const { page = 1 } = use(searchParams);
  const {
    data: { results, count } = {},
    status,
    message,
  } = use(userFetchClient(`/client/client-orders-list/?page=${page}`));

  return (
    <div>
      <div className="p-3.5 border-b border-[#7B6198] flex justify-between">
        <p className="text-2xl font-extrabold">Order info</p>
      </div>

      <div className="my-10 ">
        <QueryBoundary
          status={status}
          errorMsg={message}
          count={count}
          warningMsg="Order not found! please order something"
        >
          {results?.map((order, index) => {
            const { id, order_date, order_tracking_status, order_id } = order;
            return (
              <Collapse
                key={id}
                isDisabled={order_tracking_status === "cancelled"}
                title={
                  <Order
                    btn={order_tracking_status}
                    order_id={order_id}
                    order_date={order_date}
                  />
                }
                icon={false}
              >
                <OrderTrack status={order_tracking_status} id={id} />
              </Collapse>
            );
          })}

          {count > 10 && <Pagination totalPage={Math.ceil(count / 10)} />}
        </QueryBoundary>
      </div>
    </div>
  );
};

export default page;

function TrackPoint({ className, isCompleted = false }) {
  return (
    <div
      className={` ${
        !isCompleted && "border-2  rounded-full bg-[#4B3662]"
      } size-fit  ${className} z-50 `}
      // className={` ${
      //   !isCompleted && "border-2  rounded-full bg-[#4B3662]"
      // } size-fit absolute top-1/2 -translate-y-1/2 ${className} z-50 `}
    >
      {!isCompleted ? (
        <div className="size-[22px] rounded-full bg-white m-[5]"></div>
      ) : (
        <svg
          width={37}
          height={36}
          viewBox="0 0 37 36"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <g clipPath="url(#clip0_10_6402)">
            <circle
              cx="18.4312"
              cy={18}
              r={17}
              fill="#FF15B9"
              stroke="#FF15B9"
              strokeWidth={2}
            />
            <path
              d="M15.6437 21.5973L26.4909 10.75L27.9312 12.1903L15.6437 24.4778L9.93066 18.7665L11.3709 17.3262L15.6437 21.5973Z"
              fill="white"
            />
          </g>
          <defs>
            <clipPath id="clip0_10_6402">
              <rect
                width={36}
                height={36}
                fill="white"
                transform="translate(0.431152)"
              />
            </clipPath>
          </defs>
        </svg>
      )}
    </div>
  );
}

function OrderTrack({ status, id }) {
  let completedLineWidth = "h-[0%] md:w-[0%]";
  switch (status) {
    case "packing":
      completedLineWidth = "h-[34%] md:h-0 md:w-[34%]";
      break;
    case "out_for_delivery":
      completedLineWidth = "h-[68%] md:h-0 md:w-[68%]";
      break;
    case "delivered":
      completedLineWidth = "h-[100%] md:h-0 md:w-[100%]";
      break;
  }

  const isProcessCompleted = [
    "processing",
    "packing",
    "out_for_delivery",
    "delivered",
  ].includes(status);

  const isOutForDeliveryCompleted = ["out_for_delivery", "delivered"].includes(
    status
  );

  const isPackingCompleted = [
    "packing",
    "out_for_delivery",
    "delivered",
  ].includes(status);

  const isDeliveryCompleted = status === "delivered";

  return (
    <div className="rounded-[40px] bg-[#4B3662] p-6 md:p-10 space-y-8 md:space-y-16">
      <p className="text-lg md:text-2xl font-semibold text-center">
        Track Order
      </p>

      <div className="flex flex-row md:flex-col">
        {/* Line and TrackPoints */}
        <div className="relative mx-10 flex flex-col md:flex-row justify-between ">
          <TrackPoint isCompleted={isProcessCompleted} />
          <TrackPoint isCompleted={isPackingCompleted} />
          <TrackPoint isCompleted={isOutForDeliveryCompleted} />
          <TrackPoint isCompleted={isDeliveryCompleted} />

          {/* background line */}
          <div className="absolute top-0 bottom-0 left-1/2 -translate-x-1/2 md:left-0 md:translate-x-0 md:w-full md:max-h-0 md:bottom-0  md:top-1/2 -md:translate-y-1/2  border-2 border-white/40 rounded-full  z-10"></div>

          {/* completed line */}
          <div
            className={`absolute top-0 left-1/2 -translate-x-1/2 md:left-0 md:translate-x-0 md:top-1/2 -md:translate-y-1/2  border-2 border-[#FF15B9] rounded-full  z-20 ${completedLineWidth}`}
          ></div>
        </div>

        {/* Icons and Labels */}
        <div className="flex flex-col gap-10 mg:gap-0 md:flex-row   justify-between  md:pt-10  text-center text-sm md:text-base">
          <div className="flex flex-col xl:flex-row items-center gap-2.5 w-1/4 ">
            <Process color={isProcessCompleted ? "#FF15B9" : "white"} />
            <p
              className={`font-extrabold ${
                isProcessCompleted ? "text-[#FF15B9]" : "text-white"
              }`}
            >
              Process
            </p>
          </div>
          <div className="flex flex-col xl:flex-row items-center gap-2.5 w-1/4 ">
            <Packing color={isPackingCompleted ? "#FF15B9" : "white"} />
            <p
              className={`font-extrabold ${
                isPackingCompleted ? "text-[#FF15B9]" : "text-white"
              }`}
            >
              Packing
            </p>
          </div>
          <div className="flex flex-col xl:flex-row items-center gap-2.5 w-1/4 ">
            <Delivery color={isOutForDeliveryCompleted ? "#FF15B9" : "white"} />
            <p
              className={`font-extrabold ${
                isOutForDeliveryCompleted ? "text-[#FF15B9]" : "text-white"
              }`}
            >
              Out For Delivery
            </p>
          </div>
          <div className="flex flex-col xl:flex-row items-center gap-2.5 w-1/4 ">
            <Delivered color={isDeliveryCompleted ? "#FF15B9" : "white"} />
            <p
              className={`font-extrabold ${
                isDeliveryCompleted ? "text-[#FF15B9]" : "text-white"
              }`}
            >
              Delivered
            </p>
          </div>
        </div>
      </div>
      {status !== "delivered" && <OrderCancel id={id} status={status} />}
    </div>
  );
}

function Order({ btn = "process", order_id, order_date }) {
  const statusColor = (status) => {
    let color;
    switch (status) {
      case "process":
        color = "bg-[#127DF7]";
        break;
      case "packing":
        color = "bg-[#FF6B00]";
        break;
      case "out_for_delivery":
        color = "bg-[#9124F0]";
        break;
      case "delivered":
        color = "bg-[#03BA74]";
        break;
      case "cancelled":
        color = "bg-red-500";
        break;
      default:
        color = "bg-[#127DF7]";
    }
    return color;
  };
  return (
    <div className="my-5 border-b border-dashed border-[#4B3662] flex justify-between items-center w-full truncate">
      <div className="flex items-center gap-5  overflow-hidden">
        <Image src={orderImg} alt="bag" />
        <div className="">
          <p className="text-base font-extrabold truncate">OrderID{order_id}</p>
          <div className="flex items-center gap-[2px]">
            <svg
              width={17}
              height={16}
              viewBox="0 0 17 16"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                fillRule="evenodd"
                clipRule="evenodd"
                d="M14.6195 8.00065C14.6195 11.4067 11.8588 14.1673 8.4528 14.1673C5.0468 14.1673 2.28613 11.4067 2.28613 8.00065C2.28613 4.59465 5.0468 1.83398 8.4528 1.83398C11.8588 1.83398 14.6195 4.59465 14.6195 8.00065Z"
                stroke="#D5BBF2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d="M10.7404 9.96309L8.22705 8.46375V5.23242"
                stroke="#D5BBF2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
            <p className="text-sm text-[#D5BBF2]">
              {/* {getTimeDiffShort(order_date)} */}
            </p>
          </div>
        </div>
      </div>
      <div className="flex flex-col gap-3 ">
        <span
          className={`px-4 py-2.5 text-sm font-bold rounded-[100px] capitalize  ${statusColor(
            btn
          )}`}
        >
          {btn?.split("_")?.join(" ")}
        </span>
        <span className="text-sx text-center font-bold underline cursor-pointer ">
          Track Order
        </span>
      </div>
    </div>
  );
}

